    options?.onStdout?.call('stdout line 1\n');
    options?.onStdout?.call('{"ok":true}'); // no trailing newline: AC2
    options?.onStderr?.call('stderr line\n');
    return Ok(
      ShellExecResult(
        stdout: 'stdout line 1\n{"ok":true}',
        stderr: 'stderr line\n',
        exitCode: exitCode,
      ),
    );
  }
}

